const komp: Record<Slug, KompetenzId[]> = { messen: ["plan"], ziegel: ["material"], laengen: ["rechnen"], breiten: ["rechnen", "plan"], wasser: ["plan"], verlegen: ["ablauf"], schnitt: ["plan", "material"], bearbeiten: ["ablauf"], befestigen: ["material", "ablauf"], kontrolle: ["plan", "ablauf"] };
function basis(id: string, slug: Slug, titel: string, auftrag: string, hinweis: string, erklaerung: string) {
  return { id, titel, auftrag, hinweis, erklaerung, kompetenzen: komp[slug], szene: slug as WerkstattSzene };
}
function aktiv(id: string, slug: Slug, titel: string, auftrag: string, hinweis: string, erklaerung: string, aktivitaet: Aktivitaet): WerkstattAufgabe {
  return { ...basis(id, slug, titel, auftrag, hinweis, erklaerung), typ: "aktivitaet", aktivitaet };
}
function zuordnen(id: string, slug: Slug, titel: string, paare: [string, string][], erklaerung: string): WerkstattAufgabe {
  const auftrag = "Ordne jedem Begriff die passende Funktion oder Aussage zu.";
  return aktiv(id, slug, titel, auftrag, "Vergleiche die Funktion; ähnlich klingende Bezeichnungen können verschiedene Aufgaben haben.", erklaerung, { id, version: 1, typ: "zuordnen", titel, auftrag, erklaerung, paare: paare.map(([links, rechts], i) => ({ id: `p${i + 1}`, links, rechts })) });
}
function auswahl(id: string, slug: Slug, titel: string, situation: string, optionen: [string, boolean][], erklaerung: string): WerkstattAufgabe {
  const auftrag = "Wähle alle passenden Aussagen. Begründe für dich, welche Funktion betroffen ist.";
  return aktiv(id, slug, titel, auftrag, "Nicht nur das Aussehen betrachten: Bezug, Sitz, Wasserführung und Befestigung haben eigene Kontrollpunkte.", erklaerung, { id, version: 1, typ: "skizzenfehler", titel, auftrag, situation, erklaerung, optionen: optionen.map(([text, korrekt], i) => ({ id: `o${i + 1}`, text, korrekt })) });
}
function ordnen(id: string, slug: Slug, titel: string, texte: string[], erklaerung: string): WerkstattAufgabe {
  const auftrag = "Bringe die Arbeitsschritte mit den Pfeiltasten in die richtige Reihenfolge.";
  return aktiv(id, slug, titel, auftrag, "Bezug und Vorgaben prüfen kommt vor der Ausführung; die Ergebniskontrolle folgt danach.", erklaerung, { id, version: 1, typ: "reihenfolge", titel, auftrag, erklaerung, schritte: texte.map((text, i) => ({ id: `s${i + 1}`, text })) });
}
